ParseDecimal.example:
#include <string_view>

#include "cinux/parse.hpp"

using namespace cinux::base;

void ParseDecimalExample() {
    // /proc 下的进程目录名整个都得是数字，一个字符不对就不是数
    const Result<unsigned long> kPid = ParseDecimal("1234");
    // kPid.ok() 为真，kPid.value() == 1234
    const Result<unsigned long> kBad = ParseDecimal("12a4");
    // kBad.ok() 为假，错误码是 KernelError::kInvalidArgument
}

ParseOctal.example:
#include <string_view>

#include "cinux/parse.hpp"

using namespace cinux::base;

void ParseOctalExample() {
    // ustar 头里的大小字段是 11 个八进制数字加一个 NUL
    const Result<unsigned long> kSize = ParseOctal(std::string_view{"00000000144", 11});
    // kSize.ok() 为真，kSize.value() == 100 · 八进制 144 是十进制 100
    const Result<unsigned long> kZero = ParseOctal(std::string_view{"\0", 1});
    // kZero.ok() 为真，kZero.value() == 0 · 全 NUL 的字段读成零
}
